DO $$ DECLARE r record; BEGIN FOR r IN SELECT schemaname,tablename FROM pg_tables WHERE schemaname IN ('property360','rural','condo','municipality','solar','aitec','analysis') AND EXISTS(SELECT 1 FROM information_schema.columns c WHERE c.table_schema=schemaname AND c.table_name=tablename AND c.column_name='tenant_id') LOOP EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY',r.schemaname,r.tablename); EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I.%I',r.schemaname,r.tablename); EXECUTE format('CREATE POLICY tenant_isolation ON %I.%I USING (tenant_id = nullif(current_setting(''app.tenant_id'', true),'''')::uuid)',r.schemaname,r.tablename); END LOOP; END $$;
